contract_clause_fact(contrato_ocs_185_2020, clausula_decima_obrigações_contratado, obrigacoes, 'Apresentar, em até 10 dias úteis após a convocação, a Declaração de Informações para Fornecimento - DIF, adequadamente preenchida', 'Inciso X').
